-- ─── APEX MOTORS — Cars Seed Data ────────────────────────────────────────────
-- Run AFTER schema.sql to populate the cars table.
-- Usage:  psql -U <user> -d apex_motors -f seed_cars.sql
-- SAFE: Uses INSERT ... ON CONFLICT DO NOTHING (idempotent).
-- ─────────────────────────────────────────────────────────────────────────────

ON CONFLICT (id) DO NOTHING;

-- Reset the sequence so future INSERTs auto-increment correctly
SELECT setval('cars_id_seq', (SELECT MAX(id) FROM cars));

DO $$
BEGIN
    RAISE NOTICE 'Seed complete. % cars in inventory.', (SELECT COUNT(*) FROM cars);
END $$;
